test("閉じると、ウィンドウが閉じる", async () => {
  const fake = AppWindowFake.create();

  await fake.appWindow.close();

  expect(fake.isWindowClosed()).toBe(true);
});

test("閉じるのを拒まれたら、拒まれた理由を持つ失敗になる", async () => {
  const fake = AppWindowFake.create();
  fake.denyClose();

  const closed = await fake.appWindow.close();

  expect(closed).toStrictEqual(
    Result.err({
      message: "close_current_window: ウィンドウを閉じられない",
    }),
  );
});

test("何も開いていない間は、開いているドキュメントが無い", () => {
  expect(DocumentSession.hasOpenedDocuments(DocumentSession.Closed)).toBe(
    false,
  );
});

test("何も開いていないまま開く操作の最中でも、開いているドキュメントは無い", () => {
  expect(
    DocumentSession.hasOpenedDocuments(
      DocumentSession.beginOpening(DocumentSession.Closed),
    ),
  ).toBe(false);
});

test("何も開けずに終わった後も、開いているドキュメントは無い", () => {
  const session = DocumentSession.finishOpening(
    DocumentSession.beginOpening(DocumentSession.Closed),
    { documents: [], failure: Option.some(DialogFailure) },
  );

  expect(DocumentSession.hasOpenedDocuments(session)).toBe(false);
});

test("ドキュメントを開いた後は、開いているドキュメントがある", () => {
  const session = DocumentSession.finishOpening(
    DocumentSession.Closed,
    opened(Path),
  );

  expect(DocumentSession.hasOpenedDocuments(session)).toBe(true);
});

test("ドキュメントを開いたまま開く操作の最中でも、開いているドキュメントがある", () => {
  const session = DocumentSession.beginOpening(
    DocumentSession.finishOpening(DocumentSession.Closed, opened(Path)),
  );

  expect(DocumentSession.hasOpenedDocuments(session)).toBe(true);
});

test("ドキュメントを開いたまま次の開く操作が失敗で終わっても、開いているドキュメントがある", () => {
  const session = DocumentSession.finishOpening(
    DocumentSession.beginOpening(
      DocumentSession.finishOpening(DocumentSession.Closed, opened(Path)),
    ),
    { documents: [], failure: Option.some(DialogFailure) },
  );

  expect(DocumentSession.hasOpenedDocuments(session)).toBe(true);
});

test("開始画面でメニューのタブを閉じるを選ぶと、ウィンドウが閉じる", async () => {
  const observer = renderEditorScreen(
    { [Path]: DocumentJson.serialize(SampleDocument) },
    { open: DialogChoice.chosen(Path), save: DialogChoice.Canceled },
  );

  await observer.chooseMenu(AppMenuCommands.CloseTab);

  expect(observer.isWindowClosed()).toBe(true);
});

/*
 * 書き出しを止めて、開く操作の最中のまま開始画面に留める。開く操作の最中を「開いている
 * もの」と取り違えていれば、閉じるタブが無いまま何も起きない。
 */
test("新規作成の書き出しの最中にメニューのタブを閉じるを選ぶと、ウィンドウが閉じる", async () => {
  const observer = renderEditorScreen(
    {},
    { open: DialogChoice.Canceled, save: DialogChoice.chosen(OtherPath) },
  );
  const release = observer.files.holdWrites(OtherPath);
  await startCreate(observer);

  await observer.chooseMenu(AppMenuCommands.CloseTab);

  expect(observer.isWindowClosed()).toBe(true);
  release();
});

test("開けずに終わった開始画面でメニューのタブを閉じるを選ぶと、ウィンドウが閉じる", async () => {
  const observer = renderEditorScreen(
    {},
    { open: DialogChoice.chosen(Path), save: DialogChoice.Canceled },
  );
  await startOpen(observer);

  await observer.chooseMenu(AppMenuCommands.CloseTab);

  expect(observer.isWindowClosed()).toBe(true);
});

test("最後のタブでメニューのタブを閉じるを選んでも、ウィンドウは閉じない", async () => {
  const observer = renderEditorScreen(
    { [Path]: DocumentJson.serialize(SampleDocument) },
    { open: DialogChoice.chosen(Path), save: DialogChoice.Canceled },
  );
  await startOpen(observer);

  await observer.chooseMenu(AppMenuCommands.CloseTab);

  expect(observer.isWindowClosed()).toBe(false);
});

test("開いているタブがあるときに開けなかった理由が出ている間にメニューのタブを閉じるを選んでも、ウィンドウは閉じない", async () => {
  const observer = renderEditorScreen(
    { [Path]: DocumentJson.serialize(SampleDocument) },
    { open: DialogChoice.chosen(OtherPath), save: DialogChoice.Canceled },
  );
  await observer.dropFiles([Path]);
  await startOpen(observer);

  await observer.chooseMenu(AppMenuCommands.CloseTab);

  expect(observer.isWindowClosed()).toBe(false);
});

test("開いているタブがあるときに新規作成の書き出しの最中にメニューのタブを閉じるを選んでも、ウィンドウは閉じない", async () => {
  const observer = renderEditorScreen(
    { [Path]: DocumentJson.serialize(SampleDocument) },
    { open: DialogChoice.Canceled, save: DialogChoice.chosen(OtherPath) },
  );
  await observer.dropFiles([Path]);
  const release = observer.files.holdWrites(OtherPath);
  await startCreate(observer);

  await observer.chooseMenu(AppMenuCommands.CloseTab);

  expect(observer.isWindowClosed()).toBe(false);
  release();
});
